/* ENS5 @Bit 5 : Enable slave port 5. */
  #define ATBFUNNEL_CTRLREG_ENS5_Pos (5UL)           /*!< Position of ENS5 field.                                              */
  #define ATBFUNNEL_CTRLREG_ENS5_Msk (0x1UL << ATBFUNNEL_CTRLREG_ENS5_Pos) /*!< Bit mask of ENS5 field.                        */
  #define ATBFUNNEL_CTRLREG_ENS5_Min (0x0UL)         /*!< Min enumerator value of ENS5 field.                                  */
