  #define BICR_POWER_CONFIG_VDDAO1V8_Internal (0x0UL) /*!< Power rail is configured to use the internal regulator. This option
                                                           requires the presence of an inductor for the 1V8 DCDC regulator.*/
  #define BICR_POWER_CONFIG_VDDAO1V8_External (0x1UL) /*!< Power rail is configured to be externally powered.                  */

/* VALIDCONFIG @Bits 16..31 : Indication of valid configuration for this register. */
