  #define BICR_POWER_CONFIG_VALIDCONFIG_Invalid (0xFFFFUL) /*!< This register is not programmed with valid content. Any other
                                                                value than the value for valid.*/
  #define BICR_POWER_CONFIG_VALIDCONFIG_Valid (0xAC53UL) /*!< This register is programmed with valid content.                  */



